if (!bb.isValid() || !bb.isInside(p)) {
    return false;
}

int intersections = 0;
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dist(0.0, 1.0);

for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction
    double x, y, z;
    do {
        x = dist(gen) * 2.0 - 1.0;
        y = dist(gen) * 2.0 - 1.0;
        z = dist(gen) * 2.0 - 1.0;
    } while (x == 0.0 && y == 0.0 && z == 0.0); // Ensure non-zero vector

    // Normalize the direction
    double length = std::sqrt(x*x + y*y + z*z);
    x /= length;
    y /= length;
    z /= length;

    // Create a ray from the point in the random direction
    CGALPoint source(p.x(), p.y(), p.z());
    CGALPoint target(p.x() + x * bb.diag() * 2.0,
                     p.y() + y * bb.diag() * 2.0,
                     p.z() + z * bb.diag() * 2.0);
    CGALRay ray(source, target);

    // Count intersections
    intersections += tree.number_of_intersected_primitives(ray);
}

return (intersections % 2) == 1;

